cd /testbed && cat > test_edge_cases.py << 'EOF'
import django
from django.conf import settings

settings.configure(
    DEBUG=True,
    TEMPLATES=[{
        'BACKEND': 'django.template.backends.django.DjangoTemplates',
    }],
)

django.setup()

from django import template
from django.template import Template, Context

register = template.Library()

# Test case 1: keyword-only arg with default
@register.simple_tag
def hello(*, greeting='hello'):
    return f'{greeting} world'

# Test case 2: keyword-only arg without default
@register.simple_tag
def hi(*, greeting):
    return f'{greeting} world'

# Test case 3: mixed positional and keyword-only args
@register.simple_tag
def greet(name, *, greeting='hello'):
    return f'{greeting} {name}'

# Test case 4: multiple keyword-only args (some with defaults, some without)
@register.simple_tag
def fancy_greet(*, required_greeting, optional_suffix='!'):
    return f'{required_greeting} world{optional_suffix}'

# Test case 5: with **kwargs
@register.simple_tag
def with_varkw(**kwargs):
    return ', '.join(f'{k}={v}' for k, v in kwargs.items())

# Test case 6: positional arg with default plus keyword-only with default
@register.simple_tag
def complex_tag(name='World', *, greeting='Hello'):
    return f'{greeting}, {name}!'

from django.template import engines
engine = engines['django']
engine.engine.template_libraries['test_tags'] = register

test_cases = [
    ("keyword-only arg with default (provided)", "{% load test_tags %}{% hello greeting='hi' %}"),
    ("keyword-only arg with default (not provided)", "{% load test_tags %}{% hello %}"),
    ("keyword-only arg without default", "{% load test_tags %}{% hi greeting='hey' %}"),
    ("mixed positional and keyword-only", "{% load test_tags %}{% greet 'Alice' greeting='Hi' %}"),
    ("multiple keyword-only args", "{% load test_tags %}{% fancy_greet required_greeting='Hi' optional_suffix='.' %}"),
    ("multiple keyword-only args (only required)", "{% load test_tags %}{% fancy_greet required_greeting='Hi' %}"),
    ("with **kwargs", "{% load test_tags %}{% with_varkw foo='bar' baz='qux' %}"),
    ("positional default + keyword-only default (all provided)", "{% load test_tags %}{% complex_tag 'Alice' greeting='Hi' %}"),
    ("positional default + keyword-only default (only positional)", "{% load test_tags %}{% complex_tag 'Alice' %}"),
    ("positional default + keyword-only default (none provided)", "{% load test_tags %}{% complex_tag %}"),
]

print("Testing edge cases...")
for name, template_str in test_cases:
    print(f"\nTest: {name}")
    print(f"  Template: {template_str}")
    try:
        t = Template(template_str)
        result = t.render(Context())
        print(f"  SUCCESS: {result.strip()}")
    except Exception as e:
        print(f"  ERROR: {e}")

# Error cases
print("\n\nTesting error cases...")
error_cases = [
    ("duplicate kwarg", "{% load test_tags %}{% hi greeting='hi' greeting='hello' %}", "multiple values"),
    ("unexpected kwarg", "{% load test_tags %}{% hi greeting='hi' unknown='val' %}", "unexpected keyword argument"),
    ("missing required kwonly arg", "{% load test_tags %}{% hi %}", "did not receive value"),
    ("missing required kwonly among multiple", "{% load test_tags %}{% fancy_greet optional_suffix='.' %}", "did not receive value"),
]

for name, template_str, expected_error in error_cases:
    print(f"\nTest: {name}")
    print(f"  Template: {template_str}")
    print(f"  Expected error containing: '{expected_error}'")
    try:
        t = Template(template_str)
        result = t.render(Context())
        print(f"  UNEXPECTED SUCCESS: {result.strip()}")
    except Exception as e:
        if expected_error in str(e):
            print(f"  SUCCESS: Got expected error: {e}")
        else:
            print(f"  WRONG ERROR: {e}")
EOF
python test_edge_cases.py

cd /testbed && cat > test_inclusion_tags.py << 'EOF'
import os
import django
from django.conf import settings

# Create a temp directory for templates
os.makedirs('/tmp/test_templates', exist_ok=True)
with open('/tmp/test_templates/result.html', 'w') as f:
    f.write('{{ greeting }} world')

settings.configure(
    DEBUG=True,
    TEMPLATES=[{
        'BACKEND': 'django.template.backends.django.DjangoTemplates',
        'DIRS': ['/tmp/test_templates'],
    }],
)

django.setup()

from django import template
from django.template import Template, Context

register = template.Library()

# Inclusion tag with keyword-only arg with default
@register.inclusion_tag('result.html')
def inc_hello(*, greeting='hello'):
    return {'greeting': greeting}

# Inclusion tag with keyword-only arg without default
@register.inclusion_tag('result.html')
def inc_hi(*, greeting):
    return {'greeting': greeting}

from django.template import engines
engine = engines['django']
engine.engine.template_libraries['test_tags'] = register

print("Testing inclusion tags...")
test_cases = [
    ("inclusion tag with kwonly default (provided)", "{% load test_tags %}{% inc_hello greeting='hi' %}"),
    ("inclusion tag with kwonly default (not provided)", "{% load test_tags %}{% inc_hello %}"),
    ("inclusion tag with kwonly no default", "{% load test_tags %}{% inc_hi greeting='hey' %}"),
]

for name, template_str in test_cases:
    print(f"\nTest: {name}")
    print(f"  Template: {template_str}")
    try:
        t = Template(template_str)
        result = t.render(Context())
        print(f"  SUCCESS: {result.strip()}")
    except Exception as e:
        print(f"  ERROR: {e}")

print("\n\nTesting inclusion tag error cases...")
error_cases = [
    ("inclusion tag duplicate kwarg", "{% load test_tags %}{% inc_hi greeting='hi' greeting='hello' %}", "multiple values"),
]

for name, template_str, expected_error in error_cases:
    print(f"\nTest: {name}")
    print(f"  Template: {template_str}")
    try:
        t = Template(template_str)
        result = t.render(Context())
        print(f"  UNEXPECTED SUCCESS: {result.strip()}")
    except Exception as e:
        if expected_error in str(e):
            print(f"  SUCCESS: Got expected error: {e}")
        else:
            print(f"  WRONG ERROR: {e}")
EOF
